using MasrLab.Application.Common.Printing; using MasrLab.Infrastructure.Printing; using MasrLab.Infrastructure.Printing.Reports;
namespace MasrLab.Infrastructure.Tests.Printing;
public class OperationalReportTests { [Theory] [InlineData(PrintReportNames.WorkSheet)] [InlineData(PrintReportNames.PatientHistory)] [InlineData(PrintReportNames.Attendance)] [InlineData(PrintReportNames.PriceList)] [InlineData(PrintReportNames.Drawer)] [InlineData(PrintReportNames.Statistics)] public void Reports_RenderPdf(string name) { IReportDefinition[] all=[new WorkSheetReport(),new PatientHistoryReport(),new AttendanceReport(),new PriceListReport(),new DrawerReport(),new StatisticsReport()]; var pdf=new ReportDefinitionRegistry(all).Get(name).Render(new OperationalReportPrintDto(name,DateTime.Today,DateTime.Today,[new("Item","Value")])); Assert.Equal("%PDF-",System.Text.Encoding.ASCII.GetString(pdf,0,5)); } }
